def cZeroSumTruncateCLM (s : Finset I) : JLMS.CZeroSum 𝕜 E →L[𝕜] JLMS.CZeroSum 𝕜 E :=
  ∑ i ∈ s, (JLMS.CZeroSum.singleIsometry (𝕜 := 𝕜) (E := E) i).toContinuousLinearMap.comp
    (JLMS.CZeroSum.evalCLM i)

